const dgram = require('node:dgram');

const server = dgram.createSocket('udp4');
server.on('message', (msg, rinfo) => {
  // no connection: every datagram carries the sender's address
  server.send('pong:' + msg, rinfo.port, rinfo.address);
});

server.bind(0, '127.0.0.1', () => {           // port 0 = any free port
  const client = dgram.createSocket('udp4');
  client.on('message', (msg) => {
    console.log('client got', msg.toString()); // pong:ping
    client.close();
    server.close();
  });
  client.send('ping', server.address().port, '127.0.0.1'); // no handshake
});

