function subnetInfo(ip, prefix) {
  const toInt = (s) => s.split('.').reduce((acc, octet) => acc * 256 + Number(octet), 0);
  const toIp = (n) => [24, 16, 8, 0].map((shift) => (n >>> shift) & 255).join('.');
  const addr = toInt(ip);
  const mask = prefix === 0 ? 0 : (~0 << (32 - prefix)) >>> 0; // /26 -> 255.255.255.192
  const network = (addr & mask) >>> 0;       // clear the host bits
  const broadcast = (network | ~mask) >>> 0; // set the host bits
  const size = 2 ** (32 - prefix);           // addresses in the block
  const special = prefix >= 31;              // /31 point-to-point, /32 single host
  return {
    mask: toIp(mask),
    network: toIp(network),
    broadcast: toIp(broadcast),
    firstHost: toIp(special ? network : network + 1),
    lastHost: toIp(special ? broadcast : broadcast - 1),
    usableHosts: special ? size : size - 2, // minus network and broadcast
  };
}

static String toIp(long n) {
    return ((n >> 24) & 255) + "." + ((n >> 16) & 255) + "." + ((n >> 8) & 255) + "." + (n & 255);
}

static Map<String, String> subnetInfo(String ip, int prefix) {
    long addr = 0;
    for (String octet : ip.split("\\.")) addr = addr * 256 + Integer.parseInt(octet);
    long mask = prefix == 0 ? 0 : (0xFFFFFFFFL << (32 - prefix)) & 0xFFFFFFFFL;
    long network = addr & mask;                       // clear the host bits
    long broadcast = network | (~mask & 0xFFFFFFFFL); // set the host bits
    long size = 1L << (32 - prefix);
    boolean special = prefix >= 31;                   // /31 and /32
    Map<String, String> r = new LinkedHashMap<>();
    r.put("mask", toIp(mask));
    r.put("network", toIp(network));
    r.put("broadcast", toIp(broadcast));
    r.put("firstHost", toIp(special ? network : network + 1));
    r.put("lastHost", toIp(special ? broadcast : broadcast - 1));
    r.put("usableHosts", String.valueOf(special ? size : size - 2));
    return r;
}

const net = require('node:net');

// Listening socket: bound to a port, only accepts connections
const server = net.createServer((socket) => {
  // a NEW connected socket per client, identified by the 4-tuple
  console.log('server: connection from', socket.remoteAddress + ':' + socket.remotePort);
  socket.on('data', (data) => socket.end('echo: ' + data));
});

server.listen(0, '127.0.0.1', () => {            // port 0 = let the OS pick a free port
  const { port } = server.address();
  const client = net.connect(port, '127.0.0.1', () => {
    // the client side gets an ephemeral port chosen by the OS
    console.log('client: local port', client.localPort, '-> server port', port);
    client.write('hello');
  });
  client.on('data', (d) => console.log('client got:', d.toString()));
  client.on('close', () => server.close());
});

import java.io.*;
import java.net.*;

public class EchoDemo {
    public static void main(String[] args) throws Exception {
        InetAddress lo = InetAddress.getLoopbackAddress();
        try (ServerSocket listener = new ServerSocket(0, 50, lo)) {   // port 0 = any free port
            int port = listener.getLocalPort();
            Thread server = new Thread(() -> {
                try (Socket conn = listener.accept();                 // NEW socket per client
                     var in = new BufferedReader(new InputStreamReader(conn.getInputStream()));
                     var out = new PrintWriter(conn.getOutputStream(), true)) {
                    System.out.println("server: connection from " + conn.getRemoteSocketAddress());
                    out.println("echo: " + in.readLine());
                } catch (IOException e) {
                    throw new UncheckedIOException(e);
                }
            });
            server.start();
            try (Socket client = new Socket(lo, port);               // 3-way handshake
                 var in = new BufferedReader(new InputStreamReader(client.getInputStream()));
                 var out = new PrintWriter(client.getOutputStream(), true)) {
                System.out.println("client: local port " + client.getLocalPort() + " -> server port " + port);
                out.println("hello");
                System.out.println("client got: " + in.readLine());
            }
            server.join();
        }
    }
}
